// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address _owner) public {
        vm.assume(_owner != ownerOf(c));
        vm.prank(ownerOf(c));
        c.setOwner(_owner);
        assertTrue(c.owner() == _owner);
    }
    function ownerOf(Owned _c) internal view returns (address) {
        return _c.owner();
    }
}
